import { useState } from "react";
import { isAddress } from "viem";
import { useAccount, useChainId, useWriteContract } from "wagmi";
import {
  Card,
  Image,
  Tooltip,
  Modal,
  Input,
  Skeleton,
  notification,
} from "antd";
import { FileSearchOutlined, SendOutlined } from "@ant-design/icons";
import { getExplorer } from "helpers/networks";
import { getNetworkConfig } from "helpers/wagmi";
import { useNFTBalances } from "hooks/useNFTBalances";
import AddressInput from "./AddressInput";
import DataNotice from "./DataNotice";

// Only the two transfer entry points are needed, so declare them inline
// rather than carrying two full NFT ABIs.
const ERC721_ABI = [
  {
    type: "function",
    name: "safeTransferFrom",
    stateMutability: "nonpayable",
    inputs: [
      { name: "from", type: "address" },
      { name: "to", type: "address" },
      { name: "tokenId", type: "uint256" },
    ],
    outputs: [],
  },
];

const ERC1155_ABI = [
  {
    type: "function",
    name: "safeTransferFrom",
    stateMutability: "nonpayable",
    inputs: [
      { name: "from", type: "address" },
      { name: "to", type: "address" },
      { name: "id", type: "uint256" },
      { name: "amount", type: "uint256" },
      { name: "data", type: "bytes" },
    ],
    outputs: [],
  },
];

const { Meta } = Card;

const FALLBACK_IMAGE =
  "data:image/png;base64,";

function NFTBalance() {
  const { NFTBalances, isLoading, isSupported } = useNFTBalances();
  const { address: account } = useAccount();
  const chainId = useChainId();
  const { mutateAsync: writeContract } = useWriteContract();
  const [visible, setVisibility] = useState(false);
  const [receiverToSend, setReceiver] = useState(null);
  const [amountToSend, setAmount] = useState(null);
  const [nftToSend, setNftToSend] = useState(null);
  const [isPending, setIsPending] = useState(false);
  // networks.js is keyed by hex chain id; wagmi hands us decimal.
  const explorer = getExplorer(`0x${chainId.toString(16)}`);

  async function transfer(nft, amount, receiver) {
    if (!isAddress(receiver)) {
      notification.error({
        message: "Transfer failed",
        description: "That recipient is not a valid address.",
        placement: "bottomRight",
      });
      return;
    }

    const is1155 = nft?.contract_type === "ERC1155";
    setIsPending(true);

    try {
      await writeContract({
        address: nft.token_address,
        abi: is1155 ? ERC1155_ABI : ERC721_ABI,
        functionName: "safeTransferFrom",
        args: is1155
          ? [
              account,
              receiver,
              BigInt(nft.token_id),
              BigInt(amount ?? nft.amount ?? 1),
              "0x",
            ]
          : [account, receiver, BigInt(nft.token_id)],
      });
      notification.success({
        message: "Transfer submitted",
        description: `${nft?.name || "NFT"} is on its way to ${receiver}.`,
        placement: "bottomRight",
      });
      setIsPending(false);
      setVisibility(false);
    } catch (e) {
      notification.error({
        message: "Transfer failed",
        description: e.shortMessage || e.message,
        placement: "bottomRight",
      });
      setIsPending(false);
    }
  }

  const handleTransferClick = (nft) => {
    setNftToSend(nft);
    setVisibility(true);
  };

  const handleChange = (e) => {
    setAmount(e.target.value);
  };

  return (
    <div className="w-full max-w-5xl px-1 py-2">
      <h1 className="mb-4 text-2xl font-bold text-fg">🖼 NFT Balances</h1>
      {!isSupported ? (
        <DataNotice chainName={getNetworkConfig(chainId)?.chainName} />
      ) : (
        <div className="flex w-full flex-wrap justify-center gap-4 sm:justify-start">
          <Skeleton loading={isLoading} active>
            {NFTBalances &&
              NFTBalances.map((nft, index) => (
                <Card
                  hoverable
                  actions={[
                    <Tooltip title="View on block explorer" key="explorer">
                      <FileSearchOutlined
                        onClick={() =>
                          explorer &&
                          window.open(
                            `${explorer}/address/${nft.token_address}`,
                            "_blank",
                          )
                        }
                      />
                    </Tooltip>,
                    <Tooltip title="Transfer NFT" key="transfer">
                      <SendOutlined onClick={() => handleTransferClick(nft)} />
                    </Tooltip>,
                  ]}
                  className="w-60 overflow-hidden rounded-2xl"
                  cover={
                    <Image
                      preview={false}
                      src={nft?.image || "error"}
                      fallback={FALLBACK_IMAGE}
                      alt=""
                      className="h-[300px] object-cover"
                    />
                  }
                  key={`${nft.token_address}-${nft.token_id}-${index}`}
                >
                  <Meta title={nft.name} description={nft.token_address} />
                </Card>
              ))}
          </Skeleton>
        </div>
      )}
      <Modal
        title={`Transfer ${nftToSend?.name || "NFT"}`}
        visible={visible}
        onCancel={() => setVisibility(false)}
        onOk={() => transfer(nftToSend, amountToSend, receiverToSend)}
        confirmLoading={isPending}
        okText="Send"
      >
        <AddressInput autoFocus placeholder="Receiver" onChange={setReceiver} />
        {nftToSend && nftToSend.contract_type === "ERC1155" && (
          <Input
            placeholder="amount to send"
            onChange={(e) => handleChange(e)}
          />
        )}
      </Modal>
    </div>
  );
}

export default NFTBalance;
